#nullable enable // autogenerated

using MVZ2.GameContent.Bosses;
using MVZ2.GameContent.ProgressBars;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Bosses;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Buffs;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Level;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.krakenTransition)]
    public class KrakenTransitionBuff : BuffDefinition
    {
        public KrakenTransitionBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);

            var timer = buff.GetOrCreateTimerSeconds(PROP_TIMER, START_SECONDS);
            timer.Run();

            var level = buff.Level;
            var state = buff.GetProperty<int>(PROP_STATE);
            switch (state)
            {
                case STATE_START:
                    // 音乐放缓。
                    level.SetMusicVolume(Mathf.Clamp01(level.GetMusicVolume() - (1 / 30f)));
                    if (timer.Expired)
                    {
                        buff.SetProperty(PROP_STATE, STATE_SHAKE);
                        timer.ResetSeconds(SHAKE_SECONDS);
                        level.PlaySound(VanillaSoundID.earthquake);
                    }
                    break;
                case STATE_SHAKE:
                    level.ShakeScreen(10, 0, 1);
                    if (timer.Expired)
                    {
                        // 克拉肯出现
                        buff.SetProperty(PROP_STATE, STATE_AFTER_SHAKE);
                        timer.ResetSeconds(AFTER_SHAKE_SECONDS);
                    }
                    break;
                case STATE_AFTER_SHAKE:
                    if (timer.Expired)
                    {
                        var kraken = level.Spawn(VanillaBossID.kraken, GetKrakenPosition(level), null);
                        if (kraken != null)
                        {
                            kraken.ApplyBuffForBossRevenge(2 / 3f);
                        }
                        level.SetMusicVolume(1);
                        level.SetProgressBarToBoss(VanillaProgressBarID.kraken);
                        level.PlayMusic(VanillaMusicID.mountainBoss);
                        buff.Remove();
                    }
                    break;
            }
        }
        public static Vector3 GetKrakenPosition(LevelEngine level)
        {
            var x = level.GetEntityColumnX(level.GetMaxColumnCount() - 2);
            var z = Kraken.GetAdjustZ(level);
            var y = level.GetGroundY(x, z);
            return new Vector3(x, y, z);
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
        public static readonly VanillaBuffPropertyMeta<int> PROP_STATE = new VanillaBuffPropertyMeta<int>("state");
        public const int STATE_START = 0;
        public const int STATE_SHAKE = 1;
        public const int STATE_AFTER_SHAKE = 2;
        public const float START_SECONDS = 3f;
        public const float SHAKE_SECONDS = 3f;
        public const float AFTER_SHAKE_SECONDS = 3f;
    }
}
